{
  "outcome": "escalate",
  "rationale": "We must escalate this claim because an automated fraud flag for a duplicate claim was raised, which matches an earlier claim under CLM-0077. This decision is governed by Section 7 regarding Duplicate Claims. The key fact is that the automated findings detected a duplicate submission for the same loss.",
  "citations": [
    {
      "clause_id": "PLUS-7.2",
      "quote": "A claim for a loss that has already been reported to us, or paid, under this policy or any other policy, must be escalated to the special investigation unit."
    }
  ]
}
